def apply_color(matrix, color):
    """Apply a color to all lit pixels in a matrix.

    Args:
        matrix (list): A list of tuples representing the pixel colors.
        color (tuple): A tuple representing the RGB color to apply.

    Returns:
        list: A new list with the specified color applied to lit pixels.
    """
    return [color if pixel == 1 else (0, 0, 0) for pixel in matrix]
